#!/usr/bin/env python3
"""Makes the ID-token fixtures for tests/chatgpt_plan.rs (TP-SUB-01).

A throwaway RSA key is made in memory, used to sign the tokens below, and dropped: only the signed
tokens (id_tokens.rs) and the public key (jwks.json) are written, so no private key is ever in the
repo. The tokens are Rust constants marked `gitleaks:allow`, as the repo's other made-up test
credentials are: they're synthetic, signed by a key that no longer exists. Rerun it to replace
every fixture at once:

    python3 make.py   # needs the `cryptography` package
"""

import base64
import json
import pathlib

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding, rsa

HERE = pathlib.Path(__file__).parent
KID = "corral-test-key"
CLAIMS = {
    "iss": "https://auth.openai.com",
    "aud": "oaiapp_corral_test",
    "sub": "user-test-subject",
    "email": "anton@example.test",
    "nonce": "nonce-fixture-0001",
    "iat": 1_790_000_000,
    "exp": 1_790_003_600,
}


def b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def uint(n: int) -> str:
    return b64(n.to_bytes((n.bit_length() + 7) // 8, "big"))


key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
public = key.public_key().public_numbers()


def token(claims: dict, header: dict | None = None, sign: bool = True) -> str:
    header = header or {"alg": "RS256", "kid": KID, "typ": "JWT"}
    signing_input = f"{b64(json.dumps(header).encode())}.{b64(json.dumps(claims).encode())}"
    signature = b""
    if sign:
        signature = key.sign(signing_input.encode(), padding.PKCS1v15(), hashes.SHA256())
    return f"{signing_input}.{b64(signature)}"


good = token(CLAIMS)
head, body, sig = good.split(".")
flipped = b64(bytes([base64.urlsafe_b64decode(sig + "==")[0] ^ 1]) + base64.urlsafe_b64decode(sig + "==")[1:])

tokens = {
    "valid": good,
    "wrong_issuer": token({**CLAIMS, "iss": "https://auth.example.test"}),
    "wrong_audience": token({**CLAIMS, "aud": "oaiapp_someone_else"}),
    "expired": token({**CLAIMS, "exp": 1_789_000_000}),
    "wrong_nonce": token({**CLAIMS, "nonce": "nonce-fixture-9999"}),
    "bad_signature": f"{head}.{body}.{flipped}",
    "alg_none": token(CLAIMS, {"alg": "none", "typ": "JWT"}, sign=False),
    "alg_hs256": token(CLAIMS, {"alg": "HS256", "kid": KID, "typ": "JWT"}),
    "unknown_kid": token(CLAIMS, {"alg": "RS256", "kid": "another-key", "typ": "JWT"}),
    "no_email": token({k: v for k, v in CLAIMS.items() if k != "email"}),
}

jwks = {"keys": [{"kty": "RSA", "use": "sig", "alg": "RS256", "kid": KID, "n": uint(public.n), "e": uint(public.e)}]}

(HERE / "jwks.json").write_text(json.dumps(jwks, indent=2) + "\n")
lines = [
    "// Generated by make.py: synthetic ID tokens signed by a throwaway key (see make.py).",
    "// Don't edit by hand; rerun make.py.",
    "",
]
for name, value in tokens.items():
    lines.append(f'pub const {name.upper()}: &str = "{value}"; // gitleaks:allow (synthetic test token)')
(HERE / "id_tokens.rs").write_text("\n".join(lines) + "\n")
print("wrote jwks.json and id_tokens.rs")
